let state;try{state=JSON.parse(localStorage.getItem('nihongo-path')||'{}')}catch{state={}}
state={lang:'bn',level:'N5',saved:[],learned:[],dark:false,bookMotion:'folio',readingSize:'normal',...state};if(!['bn','en'].includes(state.lang))state.lang='bn';if(!LEVELS.includes(state.level))state.level='N5';if(!['folio','origami','calm'].includes(state.bookMotion))state.bookMotion='folio';if(!['normal','large'].includes(state.readingSize))state.readingSize='normal';for(const k of ['saved','learned'])state[k]=Array.isArray(state[k])?state[k].filter(x=>typeof x==='string'):[];
const routeFile=location.pathname.split('/').pop().toLowerCase(),levelRoute=/^n([1-5])\.html$/.exec(routeFile);let page=(levelRoute||routeFile==='extra.html')?'level':({'lessons.html':'lessons','review.html':'review','progress.html':'progress','sources.html':'sources','settings.html':'settings'})[routeFile]||'home';if(levelRoute)state.level='N'+levelRoute[1];if(routeFile==='extra.html')state.level='EXTRA';let kind=new URLSearchParams(location.search).get('section')||'vocab';if(!KINDS.includes(kind))kind='vocab';let index={},db={},reviewed={},query='',filter='all',limit=30,current=null,mode='flash',cardIndex=0,flipped=false,answered=false;let inventory={},readerIndex=0,readerBusy=false,readerOpened=false;
const t=()=>COPY[state.lang],persist=()=>localStorage.setItem('nihongo-path',JSON.stringify(state)),entryKey=(e,k=kind)=>`${k}:${e.level}:${e.id}`,title=e=>e.word||e.pattern||e.character||'',english=e=>e.meaning||e.meanings?.join('; ')||'',checked=(e,field,k=kind)=>!!reviewed[`${e.level}:${k}:${e.id}:bn:${field}`],local=e=>e.locales?.bn||{},draftAvailable=(e,field)=>['N3','N2'].includes(e.level)&&typeof(field.startsWith('examples.')?local(e).examples?.[Number(field.split('.')[1])]:local(e)[field])==='string'&&!!(field.startsWith('examples.')?local(e).examples?.[Number(field.split('.')[1])]:local(e)[field]).trim(),useBengali=(e,field,k=kind)=>(state.lang==='bn'&&checked(e,field,k))||(state.lang==='bn'&&draftAvailable(e,field)),fieldText=(e,field,k=kind)=>useBengali(e,field,k)?local(e)[field]:(field==='meaning'?english(e):field==='guidance'?e.notes||'':e[field]||''),meaning=(e,k=kind)=>fieldText(e,'meaning',k),badge=(e,field='meaning',k=kind)=>state.lang==='bn'?`<span class="review-status ${checked(e,field,k)?'checked':draftAvailable(e,field)?'draft':''}" title="${esc(checked(e,field,k)?t().ai:'অনুবাদ যাচাই হয়নি; ভুল থাকতে পারে')}">${esc(checked(e,field,k)?(field==='meaning'?t().checked:t().checkedField):draftAvailable(e,field)?'বাংলা খসড়া · যাচাই বাকি':t().pending)}</span>`:'',count=n=>index[n]||{vocab:0,grammar:0,kanji:0,extra_vocab:0};
