function nav(){for(const selector of ['#sideNav','#bottom'])$(selector).innerHTML=['home','lessons','review','progress','settings'].map((p,i)=>`<a class="navitem ${page===p||(p==='lessons'&&page==='level')?'active':''}" href="${p==='home'?'index':p}.html" ${page===p||(p==='lessons'&&page==='level')?'aria-current="page"':''}><span aria-hidden="true">${['⌂','▤','↻','◴','⚙'][i]}</span>${esc(p==='settings'?readerLabel('Settings','সেটিংস'):t()[p])}</a>`).join('')}
function bookName(n){return n==='EXTRA'?(state.lang==='bn'?'অতিরিক্ত':'EXTRA'):n}
function bookHref(n){return n.toLowerCase()+'.html'}
function progressCount(n){const members=inventory.books?.[n];if(!members)return state.learned.filter(k=>k.split(':')[1]===n).length;const keys=new Set(KINDS.flatMap(k=>(members[k]||[]).map(id=>`${k}:${n==='EXTRA'?'N1':n}:${id}`)));return state.learned.filter(k=>keys.has(k)).length}
