function bookshelf(){return `<div class="bookshelf">${LEVELS.map((n,i)=>{const d=count(n),learned=progressCount(n),total=d.vocab+d.grammar+d.kanji;return `<a class="volume" style="--book:${['#314d41','#8a8e69','#a97656','#647b7b','#474f62','#805b63'][i]}" href="${n.toLowerCase()}.html"><span class="volume-no">VOL. 0${i+1}</span><strong>${bookName(n)}</strong><span class="jp-mark" aria-hidden="true">${['芽','葉','花','樹','森','余'][i]}</span><span class="volume-title">${esc(t().levelnames[i])}</span><span class="volume-counts">${d.vocab.toLocaleString()} ${esc(t().vocab)}<br>${n==='EXTRA'?esc(t().extra):d.grammar+' '+esc(t().grammar)+' · '+d.kanji+' '+esc(t().kanji)}</span><span class="volume-arrow" aria-hidden="true">↗</span><span class="volume-edge" aria-hidden="true"></span><div class="volume-progress" aria-label="${learned} ${esc(t().learned)}"><i style="width:${Math.min(100,total?learned/total*100:0)}%"></i></div></a>`}).join('')}</div>`}
function home(){const rows=db[state.level].vocab,w=rows[new Date().getDate()%rows.length];$('#main').innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">${t().eyebrow}</span><h1>${t().hero}</h1><p>${t().intro}</p><a class="primary" href="${state.level.toLowerCase()}.html">${t().start}<span aria-hidden="true">↗</span></a><span class="hero-caption">N5 — N1 &nbsp; · &nbsp; বাংলা + ENGLISH</span></div><div class="book-scene" aria-hidden="true"><span class="scene-kanji">言</span><span class="scene-seal">日本語<br>の旅</span><div class="scene-orbit"></div><span class="floating-note">your next chapter ↘</span><div class="book-model"><div class="book-cover"><span class="book-volume">THE JAPANESE COLLECTION</span><div class="book-kanji">学</div><strong>Nihongo Path</strong><small>ONE PAGE AT A TIME</small><span class="bookmark-ribbon"></span></div></div><span class="scene-label">A LITTLE, EVERY DAY.</span></div></section><div class="collection-ribbon"><span>01 — 06</span><span>${state.lang==='bn'?'প্রতিদিন একটি নতুন অধ্যায়':'A NEW CHAPTER, EVERY DAY'}</span><span>日本語の旅</span></div><div class="section-head"><h2>${t().choose}</h2><small>${t().shelf}</small></div>${bookshelf()}<div class="two-col"><section class="paper-card daily"><div><span class="eyebrow">${t().today}</span><div class="daily-jp" lang="ja">${esc(title(w))}</div><span class="reading">${esc(w.reading)}</span><p>${esc(meaning(w,'vocab'))}</p>${badge(w,'meaning','vocab')}</div><button class="round-listen" id="dailyListen" aria-label="${t().listen}">▷</button></section><section class="paper-card"><span class="eyebrow">${t().yourProgress}</span><div class="stat-row"><div><strong>${state.learned.length}</strong><small>${t().learned}</small></div><div><strong>${state.saved.length}</strong><small>${t().saved}</small></div></div><a class="quiet-link" href="progress.html">${t().viewProgress} ↗</a></section></div><p class="notice" style="margin-top:26px">${t().quality}</p>`;$('#dailyListen').onclick=e=>speak(title(w),e.currentTarget)}
function catalog(){$('#main').innerHTML=`<span class="eyebrow">${t().shelf}</span><h1>${t().choose}</h1><p class="muted">${t().chapterIntro}</p><p class="notice">${t().quality}</p><div style="margin-top:35px">${bookshelf()}</div>`}
function selectedEntries(){return db[state.level][kind].filter(e=>{const k=entryKey(e);return(filter==='all'||filter==='core'&&e.curriculum_status!=='supplementary'||filter==='extra'&&e.curriculum_status==='supplementary'||filter==='saved'&&state.saved.includes(k)||filter==='learned'&&state.learned.includes(k))&&(!query||[title(e),e.reading,e.romaji,e.other_forms?.join(' '),english(e),meaning(e)].join(' ').toLowerCase().includes(query.toLowerCase()))})}
function summaryHTML(e,prefix='reader'){
 const k=entryKey(e);return `<span class="eyebrow">${bookName(state.level)} / ${t()[kind]}</span><h1 ${prefix==='modal'?'id="detailTitle"':''} class="reader-word" lang="ja">${esc(title(e))}</h1><p class="reading">${esc(e.reading||e.romaji)}</p><h2>${esc(meaning(e))}</h2>${badge(e)}${useBengali(e,'meaning')?`<p class="source-gloss">${esc(english(e))}</p>`:''}${e.curriculum_status==='supplementary'?`<p class="notice">${t().extraNote}</p>`:''}<div class="lesson-actions"><button class="chip" id="${prefix}-listen">▷ ${t().listen}</button><button class="chip" id="${prefix}-save">${state.saved.includes(k)?'★ '+t().savedAction:'☆ '+t().save}</button><button class="chip" id="${prefix}-learned">${state.learned.includes(k)?'✓ '+t().marked:t().mark}</button></div>${kind==='kanji'?`<div class="kanji-readings"><b>${t().onyomi}</b><br><span lang="ja">${esc(e.onyomi?.join('、')||'—')}</span><br><b>${t().kunyomi}</b><br><span lang="ja">${esc(e.kunyomi?.join('、')||'—')}</span><p class="muted">${e.strokes||0} ${t().strokes}</p></div>`:''}`;
}
function contentHTML(e){const l=local(e),formation=fieldText(e,'formation'),guidance=fieldText(e,'guidance');return `${formation?`<h3>${t().formation}</h3><div class="formation">${esc(formation)}</div>${badge(e,'formation')}`:''}${guidance?`<h3>${t().guidance}</h3><p class="guidance">${esc(guidance)}</p>${badge(e,'guidance')}`:''}${e.examples?.length?`<h3>${t().examples}</h3>${e.examples.map((x,i)=>`<section class="example"><div class="example-number">${String(i+1).padStart(2,'0')}</div><p class="ja" lang="ja">${esc(x.ja)}</p>${state.lang==='bn'&&(checked(e,'examples.'+i)||draftAvailable(e,'examples.'+i))?`<p class="translation">${esc(l.examples?.[i])}</p>`:''}<p class="en">${esc(x.en)}</p>${badge(e,'examples.'+i)}</section>`).join('')}`:kind==='kanji'?`<h3>${t().words}</h3><p lang="ja" class="guidance">${esc(e.words?.join(' · ')||title(e))}</p>`:`<div class="reader-endnote"><span aria-hidden="true">文</span><h3>${readerLabel('A word to remember','মনে রাখার একটি শব্দ')}</h3><p>${t().quality}</p></div>`}`}
function bindLessonActions(prefix,e){const k=entryKey(e);$('#'+prefix+'-listen').onclick=x=>speak(title(e),x.currentTarget);for(const [id,list]of[['save','saved'],['learned','learned']])$('#'+prefix+'-'+id).onclick=()=>{state[list]=state[list].includes(k)?state[list].filter(x=>x!==k):[...state[list],k];persist();if(prefix==='modal')openEntry(e);else{renderReader();renderIndex()}}}
function spreadHTML(e,i){return `<article class="book-spread" aria-label="${esc(readerLabel('Open book','খোলা বই'))}"><section class="paper-page paper-left" tabindex="0" aria-label="${esc(readerLabel('Left reading page','বাম পাতা'))}"><div class="page-running-head">NIHONGO PATH / ${bookName(state.level)}</div><div class="paper-body lesson-summary">${summaryHTML(e)}</div><span class="paper-number">${i*2+1}</span><span class="paper-corner" aria-hidden="true"></span></section><section class="paper-page paper-right" tabindex="0" aria-label="${esc(readerLabel('Right reading page','ডান পাতা'))}"><div class="page-running-head">${esc(t()[kind])} / ${String(i+1).padStart(3,'0')}</div><div class="paper-body lesson-content">${contentHTML(e)}</div><span class="paper-number">${i*2+2}</span><span class="paper-corner" aria-hidden="true"></span></section></article>`}
function renderReader(){const host=$('#readerScene');if(!host)return;const rows=selectedEntries();readerIndex=Math.max(0,Math.min(readerIndex,rows.length-1));if(!rows.length){host.innerHTML=`<p class="empty">${t().empty}</p>`;$('#readerControls').innerHTML='';return}const e=rows[readerIndex];current=e;const meter=$('#readingMeter');if(meter){meter.style.setProperty('--read-progress',`${(readerIndex+1)/rows.length*100}%`);meter.setAttribute('aria-valuenow',readerIndex+1);meter.setAttribute('aria-valuemax',rows.length);meter.setAttribute('aria-valuetext',`${readerIndex+1} / ${rows.length}`)}host.innerHTML=spreadHTML(e,readerIndex);bindLessonActions('reader',e);$('#readerControls').innerHTML=`<button id="previousPage" class="turn-button" ${readerIndex===0?'disabled':''}>← ${readerLabel('Previous page','আগের পাতা')}</button><div class="page-jump"><label for="readerPage">${readerLabel('Lesson','পাঠ')}</label> <input id="readerPage" type="number" min="1" max="${rows.length}" value="${readerIndex+1}" aria-label="${readerLabel('Go to lesson number','পাঠের নম্বরে যান')}"> / ${rows.length.toLocaleString()}<button id="jumpPage" class="jump-button" type="button">${readerLabel('Go','যান')}</button></div><button id="nextPage" class="turn-button" ${readerIndex===rows.length-1?'disabled':''}>${readerLabel('Next page','পরের পাতা')} →</button>`;$('#previousPage').onclick=()=>turnReader(-1);$('#nextPage').onclick=()=>turnReader(1);const jump=()=>{const input=$('#readerPage'),n=Number(input.value);if(Number.isInteger(n)&&n>=1&&n<=rows.length){readerIndex=n-1;renderReader()}else input.value=readerIndex+1};$('#readerPage').onchange=jump;$('#readerPage').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();jump()}};$('#jumpPage').onclick=jump;$('#readerLive').textContent=`${readerLabel('Lesson','পাঠ')} ${readerIndex+1} / ${rows.length}: ${title(e)}`}
function nextReaderIndex(position,direction,length){return Math.max(0,Math.min(position+direction,Math.max(0,length-1)))}
function turnReader(direction){const rows=selectedEntries(),next=nextReaderIndex(readerIndex,direction,rows.length);if(readerBusy||!rows.length||next===readerIndex)return;const host=$('#readerScene'),previous=rows[readerIndex],oldNumber=readerIndex;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches||state.bookMotion==='calm';readerIndex=next;renderReader();if(reduced)return;readerBusy=true;const leaf=document.createElement('div');leaf.className='turning-leaf '+(direction>0?'forward':'backward');leaf.setAttribute('aria-hidden','true');const front=direction>0?contentHTML(previous):summaryHTML(previous,'animation');const back=direction>0?summaryHTML(rows[next],'animation'):contentHTML(rows[next]);leaf.innerHTML=`<div class="page-ribs" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="leaf-face leaf-front"><div class="page-running-head">${bookName(state.level)} / ${oldNumber+1}</div><div class="leaf-body">${front}</div></div><div class="leaf-face leaf-back"><div class="page-running-head">${bookName(state.level)} / ${next+1}</div><div class="leaf-body">${back}</div></div>`;host.append(leaf);host.classList.add('is-turning');$$('#readerControls button').forEach(b=>b.disabled=true);const finish=()=>{if(!readerBusy)return;leaf.remove();host.classList.remove('is-turning');readerBusy=false;renderReader()};leaf.addEventListener('animationend',finish,{once:true});setTimeout(finish,1000)}
function renderIndex(){const host=$('#chapterIndex');if(!host)return;const rows=selectedEntries();host.innerHTML=`<div class="results-caption"><span>${rows.length.toLocaleString()} ${t().found}</span><span>${bookName(state.level)} / ${t()[kind]}</span></div><div class="entry-grid">${rows.slice(0,limit).map((e,i)=>`<button class="entry" data-entry="${esc(e.id)}"><span class="entry-index">${String(i+1).padStart(3,'0')}</span><span class="entry-state">${state.saved.includes(entryKey(e))?'★':''} ${state.learned.includes(entryKey(e))?'✓':''}</span><strong class="entry-word" lang="ja">${esc(title(e))}</strong><span class="entry-reading">${esc(e.reading||e.romaji)}</span><p class="entry-meaning">${esc(meaning(e))}</p>${badge(e)}</button>`).join('')}</div>${rows.length>limit?`<button id="moreLessons" class="chip load-more">${t().more} ↓</button>`:''}`;$$('[data-entry]').forEach(b=>b.onclick=()=>{readerIndex=rows.findIndex(e=>e.id===b.dataset.entry);renderReader();$('#readerScene').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});if($('#moreLessons'))$('#moreLessons').onclick=()=>{limit+=60;renderIndex()}}
function results(){renderReader();renderIndex()}
function level(){const d=db[state.level],i=LEVELS.indexOf(state.level);if(state.level==='EXTRA')kind='vocab';$('#main').innerHTML=`<a class="back-link" href="lessons.html">← ${t().allLevels}</a><section class="chapter-header"><div><span class="eyebrow">${t().chapter} 0${i+1} / THE JAPANESE COLLECTION</span><h1>${bookName(state.level)} · ${t().levelnames[i]}</h1><p class="muted">${state.level==='EXTRA'?t().extraNote:t().chapterIntro}</p></div><span class="chapter-number" aria-hidden="true">0${i+1}</span></section>${['N1','N2','N3','N4'].includes(state.level)?`<p class="notice"><a href="study-packs.html?level=${state.level}">${readerLabel('Explore Bengali study packs ↗','বাংলা স্টাডি প্যাক দেখুন ↗')}</a></p>`:''}<nav class="subject-tabs" aria-label="Lesson subjects">${(state.level==='EXTRA'?['vocab']:KINDS).map(k=>`<a class="subject ${kind===k?'active':''}" href="${bookHref(state.level)}?section=${k}" ${kind===k?'aria-current="page"':''}>${t()[k]}<small>${d[k].length.toLocaleString()}</small></a>`).join('')}</nav><section class="reader-desk"><div class="reader-topline"><span>${readerLabel('THE OPEN BOOK','খোলা বই')}</span><span>${readerLabel('Use ← → keys or swipe to turn a page','← → চাপুন অথবা সোয়াইপ করে পাতা উল্টান')}</span></div><div class="book-reader ${readerOpened?'':'cover-opening'}" data-cover="${bookName(state.level)}"><div id="readingMeter" class="reading-meter" role="progressbar" aria-label="Reading position" aria-valuemin="1"></div><div id="readerScene" class="reader-scene"></div></div><nav id="readerControls" class="reader-controls" aria-label="${readerLabel('Book page navigation','বইয়ের পাতা পরিবর্তন')}"></nav><p id="readerLive" class="sr-only" aria-live="polite"></p></section><details class="chapter-index"><summary>${readerLabel('Contents & search','সূচিপত্র ও খোঁজ')}</summary><div class="toolbar"><div class="search-wrap"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="${t().searchLabel}" placeholder="${t().search}" value="${esc(query)}"></div></div><div class="filters">${['all','saved','learned'].map(f=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${t()[f]}</button>`).join('')}</div><div id="chapterIndex"></div></details><p class="notice reader-quality">${t().quality}</p>`;$('#search').oninput=e=>{query=e.target.value;limit=30;readerIndex=0;results()};$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;readerIndex=0;limit=30;level();$('.chapter-index').open=true});results();readerOpened=true;let touch=null;$('#readerScene').addEventListener('touchstart',e=>{const p=e.changedTouches[0];touch={x:p.clientX,y:p.clientY}},{passive:true});$('#readerScene').addEventListener('touchend',e=>{if(!touch)return;const p=e.changedTouches[0],dx=p.clientX-touch.x,dy=p.clientY-touch.y;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5)turnReader(dx<0?1:-1);touch=null},{passive:true});document.title=`${bookName(state.level)} ${t()[kind]} · Nihongo Path Books`}

function speak(text,button){if(window.NihongoSpeech)window.NihongoSpeech.play(text,button);else{const p=document.createElement('p');p.className='speech-status';p.textContent=state.lang==='bn'?'অডিও এখন পাওয়া যাচ্ছে না।':'Audio is currently unavailable.';button.after(p)}}
function openEntry(e){current=e;$('#detailBody').innerHTML=`<article class="lesson-book"><section class="lesson-summary">${summaryHTML(e,'modal')}</section><section class="lesson-content">${contentHTML(e)}</section></article>`;bindLessonActions('modal',e);if(!$('#detail').open)$('#detail').showModal()}
function practice(){const all=db[state.level].vocab,saved=all.filter(e=>state.saved.includes(entryKey(e,'vocab'))),list=saved.length?saved:all,e=list[cardIndex%list.length];if(!e){$('#main').innerHTML=`<p class="empty">${t().reviewNone}</p>`;return}$('#main').innerHTML=`<span class="eyebrow">A DAILY RITUAL</span><h1>${t().review}</h1><p class="muted">${t().practiceIntro}</p><div class="practice-toolbar"><button id="flashMode" class="chip ${mode==='flash'?'active':''}">${t().flash}</button><button id="quizMode" class="chip ${mode==='quiz'?'active':''}">${t().quiz}</button><select id="practiceLevel" aria-label="${t().level}">${LEVELS.map(n=>`<option value="${n}" ${state.level===n?'selected':''}>${bookName(n)}</option>`).join('')}</select></div><section class="practice-card"><span class="eyebrow">${t().card} ${String(cardIndex%list.length+1).padStart(3,'0')} / ${list.length}</span><div class="practice-word" lang="ja">${esc(title(e))}</div><p class="muted">${esc(e.reading)}</p>${mode==='flash'?`<div class="practice-answer">${flipped?esc(meaning(e,'vocab')):'—'}</div>${flipped?badge(e,'meaning','vocab'):''}<div><button id="flipCard" class="primary">${flipped?t().next:t().reveal} <span>↗</span></button></div>`:`<div id="answers" class="answer-grid"></div><p id="feedback" class="practice-feedback" role="status"></p><button id="nextQuestion" class="primary" hidden>${t().next} ↗</button>`}</section><p class="practice-note">${t().practiceNote}</p>`;$('#flashMode').onclick=()=>{mode='flash';flipped=false;practice()};$('#quizMode').onclick=()=>{mode='quiz';practice()};$('#practiceLevel').onchange=async ev=>{const n=ev.target.value;ev.target.disabled=true;try{await loadLevel(n);state.level=n;cardIndex=0;flipped=false;persist();practice()}catch{showLoadError()}};if(mode==='flash')$('#flipCard').onclick=()=>{if(flipped)cardIndex++;flipped=!flipped;practice()};else{answered=false;const used=new Set([meaning(e,'vocab')]);const candidates=shuffle(all.filter(x=>x.id!==e.id));const opts=[e];for(const x of candidates){const m=meaning(x,'vocab');if(!used.has(m)){used.add(m);opts.push(x)}if(opts.length===4)break}shuffle(opts);$('#answers').innerHTML=opts.map((x,i)=>`<button class="answer" data-answer="${i}">${esc(meaning(x,'vocab'))}</button>`).join('');$$('[data-answer]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const ok=opts[+b.dataset.answer].id===e.id;$$('[data-answer]').forEach(a=>{a.disabled=true;if(opts[+a.dataset.answer].id===e.id)a.classList.add('correct')});if(!ok)b.classList.add('incorrect');$('#feedback').textContent=ok?t().right:t().wrong+': '+meaning(e,'vocab');$('#nextQuestion').hidden=false});$('#nextQuestion').onclick=()=>{cardIndex++;practice()}}}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function progress(){$('#main').innerHTML=`<span class="eyebrow">${t().overview}</span><h1>${t().yourProgress}</h1><p class="muted">${t().progressIntro}</p><div class="two-col"><section class="paper-card"><div class="stat-row"><div><strong>${state.learned.length}</strong><small>${t().learned}</small></div><div><strong>${state.saved.length}</strong><small>${t().saved}</small></div></div></section><section class="paper-card"><span class="eyebrow">${t().updated}</span><p class="notice" style="margin-top:15px">${t().local}</p><div class="filters"><button class="chip" id="exportProgress">↓ ${t().export}</button><button class="chip" id="importProgress">↑ ${t().import}</button><input type="file" id="progressFile" accept="application/json,.json" hidden></div><p id="importStatus" role="status"></p></section></div><div class="progress-list">${LEVELS.map((n,i)=>{const d=count(n),total=d.vocab+d.grammar+d.kanji,done=progressCount(n);return `<section class="progress-item"><strong>${bookName(n)}</strong><div><span>${t().levelnames[i]}</span><small class="muted" style="display:block">${done.toLocaleString()} / ${total.toLocaleString()} ${t().learned}</small><div class="progress-track"><i style="width:${Math.min(100,done/total*100)}%"></i></div></div><a class="quiet-link" href="${n.toLowerCase()}.html">${t().read} ↗</a></section>`}).join('')}</div>`;$('#exportProgress').onclick=()=>{const blob=new Blob([JSON.stringify({format:'nihongo-path-progress-v1',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nihongo-path-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#importStatus').textContent=t().downloaded};$('#importProgress').onclick=()=>$('#progressFile').click();$('#progressFile').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error();const parsed=JSON.parse(await f.text()),s=parsed.state||parsed;if(!s||!Array.isArray(s.saved)||!Array.isArray(s.learned)||![...s.saved,...s.learned].every(x=>typeof x==='string'&&/^(vocab|grammar|kanji):N[1-5]:.+$/.test(x)))throw Error();state.saved=[...new Set([...state.saved,...s.saved])];state.learned=[...new Set([...state.learned,...s.learned])];persist();progress();$('#importStatus').textContent=t().imported}catch{$('#importStatus').textContent=t().invalid}}}
function sources(){const totals=KINDS.map(k=>`${Object.values(index).reduce((n,d)=>n+d[k],0).toLocaleString()} ${t()[k]}`).join(' · ');$('#main').innerHTML=`<article class="sources-content"><span class="eyebrow">SOURCE NOTES / COLOPHON</span><h1>${t().sources}</h1><p>${t().sourceIntro}</p><p><strong>${totals}</strong></p><h2>${t().reviewTitle}</h2><p>${t().reviewText}</p><p><a href="data/review-progress.json">Review progress</a> · <a href="data/review-status.json">Field-level review status</a></p><h2>${t().attribution}</h2><p>${t().sourceList}</p><ul><li><a href="https://github.com/evanclan/OpenJLPT">OpenJLPT</a> · <a href="data/NOTICE.md">Attribution</a> · <a href="data/LICENSE">CC BY-SA 4.0</a></li><li><a href="https://github.com/jkindrix/japanese-language-data">Japanese Language Data</a> · <a href="data/SUPPLEMENT-ATTRIBUTION.md">Supplement attribution</a></li><li><a href="https://hanabira.org">Hanabira</a> · <a href="data/HANABIRA-ATTRIBUTION.md">Attribution</a></li><li><a href="data/audit.json">${t().dataAudit}</a> · <a href="data/coverage.json">Coverage</a> · <a href="data/reference-audit.json">Reference inventory</a></li></ul><p>${t().extraNote}</p><h2>Design & animation</h2><p>Independent book-inspired interface. Theme transition inspiration: <a href="https://skiper-ui.com/v1/skiper26">Skiper UI — Theme Toggle #26</a>. The interaction uses the browser View Transition API, with a reduced-motion fallback. No paid Skiper components are included.</p><p>${t().local}</p></article>`}
function settings(){
 const r=readerLabel;
 $('#main').innerHTML=`<span class="eyebrow">YOUR READING STUDIO</span><h1>${r('Make it your own.','নিজের মতো করে পড়ুন।')}</h1><p class="muted">${r('Small details. A better reading ritual.','ছোট ছোট পছন্দে আরও সুন্দর পড়ার অভিজ্ঞতা।')}</p><div class="settings-grid"><section class="paper-card settings-card"><span class="eyebrow">01 / MOTION</span><h2>${r('The art of turning a page','পাতা ওল্টানোর শিল্প')}</h2><label for="bookMotion">${r('Book animation','বইয়ের অ্যানিমেশন')}</label><select id="bookMotion"><option value="folio" ${state.bookMotion==='folio'?'selected':''}>Folio — ${r('silk & shadow','আলো-ছায়ার ঢেউ')}</option><option value="origami" ${state.bookMotion==='origami'?'selected':''}>Origami — ${r('folded paper','কাগজের ভাঁজ')}</option><option value="calm" ${state.bookMotion==='calm'?'selected':''}>Calm — ${r('instant page','অ্যানিমেশন ছাড়া')}</option></select><div class="folio-demo" aria-hidden="true"><div class="demo-paper"><span>01</span><strong>学</strong><small>NIHONGO PATH</small></div><div class="demo-leaf"><strong>夢</strong></div></div><button class="chip" id="previewMotion">${r('Preview page turn','অ্যানিমেশন দেখুন')} ↗</button><p class="muted settings-note">${r('Your device’s reduced-motion preference always takes priority.','ডিভাইসে অ্যানিমেশন কমানোর সেটিংস চালু থাকলে সেটিই অনুসরণ করা হবে।')}</p></section><section class="paper-card settings-card"><span class="eyebrow">02 / COMFORT</span><h2>${r('Room to read','পড়ার স্বাচ্ছন্দ্য')}</h2><label for="readingSize">${r('Lesson text size','পাঠের অক্ষরের আকার')}</label><select id="readingSize"><option value="normal" ${state.readingSize==='normal'?'selected':''}>${r('Standard','সাধারণ')}</option><option value="large" ${state.readingSize==='large'?'selected':''}>${r('Large','বড়')}</option></select><p class="settings-sample" lang="ja">少しずつ、毎日。</p><p class="muted">${r('A little, every day.','অল্প অল্প করে, প্রতিদিন।')}</p><a class="quiet-link" href="progress.html">${r('Export or import your progress','অগ্রগতি এক্সপোর্ট বা ইমপোর্ট করুন')} ↗</a></section><section class="paper-card settings-card contact-card"><span class="eyebrow">03 / KEEP IN TOUCH</span><h2>Hossain Najmul</h2><p class="muted">${r('Ideas, feedback, or a lesson correction? Reach the creator on WhatsApp.','পরামর্শ, মতামত বা পাঠের ভুল জানাতে WhatsApp-এ যোগাযোগ করুন।')}</p><a class="whatsapp-contact" href="https://wa.me/817090366509" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp Hossain Najmul, +81 70-9036-6509"><svg viewBox="0 0 32 32" aria-hidden="true"><path fill="currentColor" d="M16 3a13 13 0 0 0-11.2 19.6L3 29l6.6-1.7A13 13 0 1 0 16 3Zm0 23.6a10.6 10.6 0 0 1-5.4-1.5l-.4-.2-3.9 1 1-3.8-.3-.4A10.6 10.6 0 1 1 16 26.6Z"/><path fill="currentColor" d="M12.1 9.5c-.3-.7-.6-.7-.9-.7h-.7c-.3 0-.7.1-1 .5-.4.4-1.3 1.3-1.3 3.2s1.4 3.8 1.6 4.1c.2.3 2.8 4.3 6.8 6 .9.4 1.7.6 2.3.7 1 .3 1.9.2 2.6.2.8-.2 2.5-1 2.8-2 .4-1 .4-1.9.3-2.1-.2-.2-.4-.3-.9-.6l-2.7-1.3c-.4-.2-.7-.3-1 .2l-1.3 1.5c-.2.3-.5.3-.9.1-.5-.2-1.9-.7-3.5-2.2-1.3-1.2-2.2-2.6-2.5-3.1-.2-.4 0-.7.2-.9l.7-.8.5-.8c.2-.3.1-.6 0-.8l-1.1-2.5Z"/></svg><span>WhatsApp<small>+81 70-9036-6509</small></span><b aria-hidden="true">↗</b></a></section><section class="paper-card settings-card"><span class="eyebrow">04 / THE DETAILS</span><h2>${r('About this library','এই বইঘর সম্পর্কে')}</h2><div class="settings-links"><a href="sources.html">${r('Sources & translation review','উৎস ও অনুবাদের যাচাই')} ↗</a><a href="privacy.html">${r('Privacy & advertising','গোপনীয়তা ও বিজ্ঞাপন')} ↗</a><a href="https://skiper-ui.com/v1/skiper26" target="_blank" rel="noopener">Skiper UI · ${r('motion inspiration','অ্যানিমেশনের অনুপ্রেরণা')} ↗</a></div><p class="muted settings-note">${r('Preferences and progress stay in this browser.','পছন্দ ও অগ্রগতি এই ব্রাউজারেই সংরক্ষিত থাকে।')}</p></section></div><p id="settingsStatus" class="sr-only" role="status"></p>`;
 $('#bookMotion').onchange=e=>{state.bookMotion=e.target.value;persist();paintTheme();$('#settingsStatus').textContent=r('Animation saved','অ্যানিমেশন সংরক্ষিত হয়েছে')};
 $('#readingSize').onchange=e=>{state.readingSize=e.target.value;persist();paintTheme();$('#settingsStatus').textContent=r('Text size saved','অক্ষরের আকার সংরক্ষিত হয়েছে')};
 $('#previewMotion').onclick=()=>{const demo=$('.folio-demo');if(matchMedia('(prefers-reduced-motion: reduce)').matches||state.bookMotion==='calm'){demo.classList.toggle('demo-instant');return}demo.classList.remove('is-previewing');void demo.offsetWidth;demo.classList.add('is-previewing')};
}
function render(){document.documentElement.lang=state.lang;paintTheme();$('#language').value=state.lang;$('#theme').setAttribute('aria-label',t().theme);$('#closeDetail').setAttribute('aria-label',t().close);nav();window.updateAdLabel?.(state.lang);({home,lessons:catalog,level,review:practice,progress,sources,settings}[page]||home)();document.dispatchEvent(new Event('nihongo:render'));if(page!=='level')document.title=`${page==='settings'?readerLabel('Settings','সেটিংস'):t()[page]||'Nihongo Path'} · Nihongo Path Books`}
async function loadLevel(n){if(db[n])return;const res=await fetch(`data/${n.toLowerCase()}.json?v=${VERSION}`);if(!res.ok)throw Error(n);const data=await res.json();if(!KINDS.every(k=>Array.isArray(data[k])))throw Error('Invalid curriculum');db[n]=data}
function showLoadError(){$('#main').innerHTML=`<p class="empty">${t().loadError}</p><button id="retryLoad" class="chip">${t().retry}</button>`;$('#retryLoad').onclick=()=>location.reload()}
$('#language').onchange=e=>{state.lang=e.target.value;persist();render();if($('#detail').open&&current)openEntry(current)};
$('#theme').onclick=ev=>{state.dark=!state.dark;persist();const change=()=>paintTheme();if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.style.setProperty('--theme-x',`${ev.clientX||innerWidth-50}px`);document.documentElement.style.setProperty('--theme-y',`${ev.clientY||40}px`);document.startViewTransition(change)}else change()};
$('#closeDetail').onclick=()=>{$('#detail').close();if(page==='level'){renderReader();renderIndex()}};$('#detail').onclick=ev=>{if(ev.target===$('#detail')){$('#detail').close();if(page==='level'){renderReader();renderIndex()}}};$('#detail').addEventListener('close',()=>{if(page==='level'){renderReader();renderIndex()}});
document.addEventListener('keydown',ev=>{if(page!=='level'||$('#detail').open||ev.altKey||ev.ctrlKey||ev.metaKey||ev.shiftKey)return;const target=ev.target;if(target?.matches?.('input,select,textarea,[contenteditable]'))return;if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'){ev.preventDefault();turnReader(ev.key==='ArrowRight'?1:-1)}});
paintTheme();$('#main').innerHTML=`<div class="loading">${t().loading}</div>`;
(async()=>{const [response,status,bookInventory]=await Promise.all([fetch(`data/index.json?v=${VERSION}`),fetch(`data/review-status.json?v=${VERSION}`).then(r=>r.ok?r.json():{}).catch(()=>({})),fetch(`data/book-inventory.json?v=${VERSION}`).then(r=>r.ok?r.json():{}).catch(()=>({}))]);inventory=bookInventory;if(!response.ok)throw Error('Index unavailable');index=await response.json();reviewed=status;for(const n of LEVELS)if(!index[n])throw Error('Incomplete index');if(['home','level','review'].includes(page))await loadLevel(state.level);render()})().catch(showLoadError);
